statement:
A keypad has 9 buttons, numbered 1 to 9, and you decide which lowercase letters each button types. Your layout must follow these rules:

- all 26 lowercase English letters are placed on the keypad, each on exactly one button;
- a button holds at most 3 letters, in an order you also choose;
- typing the 1st letter of a button takes 1 press, the 2nd takes 2 presses and the 3rd takes 3 presses.

Given a string `s`, choose the layout that makes typing `s` cheapest and return that smallest total number of presses.

validator:
function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  return null;
}

reference:
function minimumKeypresses(s) {
  const count = new Array(26).fill(0);
  for (const ch of s) {
    count[ch.charCodeAt(0) - 97]++;
  }
  count.sort((a, b) => b - a);

  let presses = 0;
  for (let rank = 0; rank < 26; rank++) {
    const cost = Math.floor(rank / 9) + 1;
    presses += count[rank] * cost;
  }
  return presses;
}

