function minimumKeypresses(s) {
  // Exhaustive DP: give each used letter a slot level (1, 2 or 3 presses), at most 9 letters per level.
  const freq = new Map();
  for (const ch of s) freq.set(ch, (freq.get(ch) || 0) + 1);
  const values = [...freq.values()];
  const memo = new Map();
  const best = (j, one, two) => {
    if (j === values.length) return 0;
    const key = j * 100 + one * 10 + two;
    if (memo.has(key)) return memo.get(key);
    const three = j - one - two;
    let result = Infinity;
    if (one < 9) result = Math.min(result, values[j] + best(j + 1, one + 1, two));
    if (two < 9) result = Math.min(result, 2 * values[j] + best(j + 1, one, two + 1));
    if (three < 9) result = Math.min(result, 3 * values[j] + best(j + 1, one, two));
    memo.set(key, result);
    return result;
  };
  return best(0, 0, 0);
}

