function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alphabet = rand() < 0.4 ? 26 : 1 + Math.floor(rand() * 12);
  const weights = Array.from({ length: alphabet }, () => 1 + Math.floor(rand() * 20));
  const sum = weights.reduce((a, b) => a + b, 0);
  const pickLetter = () => {
    let r = rand() * sum;
    for (let i = 0; i < alphabet; i++) {
      r -= weights[i];
      if (r < 0) return letters[i];
    }
    return letters[alphabet - 1];
  };
  const n = size === 'small' ? 1 + Math.floor(rand() * 14) : 8000 + Math.floor(rand() * 2001);
  let s = '';
  for (let i = 0; i < n; i++) s += pickLetter();
  return [s];
}
